//#region src/tables/opentype.js
let LangSysTable = new Struct({
	reserved: new Reserved(uint16),
	reqFeatureIndex: uint16,
	featureCount: uint16,
	featureIndexes: new ArrayT(uint16, "featureCount")
});
let LangSysRecord = new Struct({
	tag: new StringT(4),
	langSys: new Pointer(uint16, LangSysTable, { type: "parent" })
});
let Script = new Struct({
	defaultLangSys: new Pointer(uint16, LangSysTable),
	count: uint16,
	langSysRecords: new ArrayT(LangSysRecord, "count")
});
let ScriptRecord = new Struct({
	tag: new StringT(4),
	script: new Pointer(uint16, Script, { type: "parent" })
});
let ScriptList = new ArrayT(ScriptRecord, uint16);
let FeatureParams = new Struct({
	version: uint16,
	nameID: uint16
});
let Feature = new Struct({
	featureParams: new Pointer(uint16, FeatureParams),
	lookupCount: uint16,
	lookupListIndexes: new ArrayT(uint16, "lookupCount")
});
let FeatureRecord = new Struct({
	tag: new StringT(4),
	feature: new Pointer(uint16, Feature, { type: "parent" })
});
let FeatureList = new ArrayT(FeatureRecord, uint16);
let LookupFlags = new Struct({
	markAttachmentType: uint8,
	flags: new Bitfield(uint8, [
		"rightToLeft",
		"ignoreBaseGlyphs",
		"ignoreLigatures",
		"ignoreMarks",
		"useMarkFilteringSet"
	])
});
function LookupList(SubTable) {
	let Lookup = new Struct({
		lookupType: uint16,
		flags: LookupFlags,
		subTableCount: uint16,
		subTables: new ArrayT(new Pointer(uint16, SubTable), "subTableCount"),
		markFilteringSet: new Optional_Optional(uint16, (t) => t.flags.flags.useMarkFilteringSet)
	});
	return new LazyArray(new Pointer(uint16, Lookup), uint16);
}
let RangeRecord = new Struct({
	start: uint16,
	end: uint16,
	startCoverageIndex: uint16
});
let Coverage = new VersionedStruct(uint16, {
	1: {
		glyphCount: uint16,
		glyphs: new ArrayT(uint16, "glyphCount")
	},
	2: {
		rangeCount: uint16,
		rangeRecords: new ArrayT(RangeRecord, "rangeCount")
	}
});
let ClassRangeRecord = new Struct({
	start: uint16,
	end: uint16,
	class: uint16
});
let ClassDef = new VersionedStruct(uint16, {
	1: {
		startGlyph: uint16,
		glyphCount: uint16,
		classValueArray: new ArrayT(uint16, "glyphCount")
	},
	2: {
		classRangeCount: uint16,
		classRangeRecord: new ArrayT(ClassRangeRecord, "classRangeCount")
	}
});
let Device = new Struct({
	a: uint16,
	b: uint16,
	deltaFormat: uint16
});
let LookupRecord = new Struct({
	sequenceIndex: uint16,
	lookupListIndex: uint16
});
let Rule = new Struct({
	glyphCount: uint16,
	lookupCount: uint16,
	input: new ArrayT(uint16, (t) => t.glyphCount - 1),
	lookupRecords: new ArrayT(LookupRecord, "lookupCount")
});
let RuleSet = new ArrayT(new Pointer(uint16, Rule), uint16);
let ClassRule = new Struct({
	glyphCount: uint16,
	lookupCount: uint16,
	classes: new ArrayT(uint16, (t) => t.glyphCount - 1),
	lookupRecords: new ArrayT(LookupRecord, "lookupCount")
});
let ClassSet = new ArrayT(new Pointer(uint16, ClassRule), uint16);
let Context = new VersionedStruct(uint16, {
	1: {
		coverage: new Pointer(uint16, Coverage),
		ruleSetCount: uint16,
		ruleSets: new ArrayT(new Pointer(uint16, RuleSet), "ruleSetCount")
	},
	2: {
		coverage: new Pointer(uint16, Coverage),
		classDef: new Pointer(uint16, ClassDef),
		classSetCnt: uint16,
		classSet: new ArrayT(new Pointer(uint16, ClassSet), "classSetCnt")
	},
	3: {
		glyphCount: uint16,
		lookupCount: uint16,
		coverages: new ArrayT(new Pointer(uint16, Coverage), "glyphCount"),
		lookupRecords: new ArrayT(LookupRecord, "lookupCount")
	}
});
